"use strict";(self.webpackChunksedelpeuch_net=self.webpackChunksedelpeuch_net||[]).push([[79811],{49923(e,n,t){t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>o,default:()=>d,frontMatter:()=>a,metadata:()=>i,toc:()=>c});const i=JSON.parse('{"id":"scolarite/cpbx/s4/projet/memoire","title":"M\xe9moire : r\xe9sum\xe9 et introduction","description":"M\xe9moire du projet sur les interfaces cerveau-machine pour la communication \xe9crite : r\xe9sum\xe9 en fran\xe7ais et en anglais, remerciements, avant-propos, glossaire, plan et introduction.","source":"@site/docs/scolarite/cpbx/s4/projet/memoire.md","sourceDirName":"scolarite/cpbx/s4/projet","slug":"/scolarite/cpbx/s4/projet/memoire","permalink":"/docs/scolarite/cpbx/s4/projet/memoire","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1792955287000,"sidebarPosition":5,"frontMatter":{"title":"M\xe9moire : r\xe9sum\xe9 et introduction","description":"M\xe9moire du projet sur les interfaces cerveau-machine pour la communication \xe9crite : r\xe9sum\xe9 en fran\xe7ais et en anglais, remerciements, avant-propos, glossaire, plan et introduction.","sidebar_position":5},"sidebar":"tutorialSidebar","previous":{"title":"Synth\xe8se culturelle","permalink":"/docs/scolarite/cpbx/s4/projet/synthese-culturelle"},"next":{"title":"Activit\xe9 c\xe9r\xe9brale, origine des signaux exploitables","permalink":"/docs/scolarite/cpbx/s4/projet/activite-cerebrale"}}');var s=t(74848),r=t(28453);const a={title:"M\xe9moire : r\xe9sum\xe9 et introduction",description:"M\xe9moire du projet sur les interfaces cerveau-machine pour la communication \xe9crite : r\xe9sum\xe9 en fran\xe7ais et en anglais, remerciements, avant-propos, glossaire, plan et introduction.",sidebar_position:5},o=void 0,l={},c=[{value:"R\xe9sum\xe9",id:"r\xe9sum\xe9",level:2},{value:"Abstract",id:"abstract",level:2},{value:"Remerciements",id:"remerciements",level:2},{value:"Avant-propos",id:"avant-propos",level:2},{value:"Glossaire",id:"glossaire",level:2},{value:"Plan du m\xe9moire",id:"plan-du-m\xe9moire",level:2},{value:"Introduction",id:"introduction",level:2}];function u(e){const n={a:"a",h2:"h2",li:"li",ol:"ol",p:"p",section:"section",strong:"strong",sup:"sup",ul:"ul",...(0,r.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"L'utilisation des Interfaces Cerveau-Machine dans la communication \xe9crite."})," Projet final du Cycle Pr\xe9paratoire de Bordeaux, Universit\xe9 de Bordeaux. M\xe9moire r\xe9dig\xe9 par Delpeuch S\xe9bastien, Escobosa Valentin et Javerzat Natacha, 9 mai 2019, encadr\xe9 par L\xe9a Pillette."]}),"\n",(0,s.jsx)(n.h2,{id:"r\xe9sum\xe9",children:"R\xe9sum\xe9"}),"\n",(0,s.jsx)(n.p,{children:"Les Interfaces Cerveau-Machine (ICM) sont des outils permettant la communication entre le cerveau et un dispositif externe. Le concept \xe9merge d'abord dans les r\xe9cits de science-fiction, mais le d\xe9veloppement des neurosciences dans les ann\xe9es 1970 rend envisageable la cr\xe9ation de mod\xe8les r\xe9els."}),"\n",(0,s.jsx)(n.p,{children:"La d\xe9couverte des structures et des m\xe9canismes r\xe9gissant le fonctionnement du cerveau permet d'appr\xe9hender la nature des signaux inh\xe9rents \xe0 l'activit\xe9 c\xe9r\xe9brale. Plusieurs dispositifs de mesure non invasifs comme l'\xe9lectroenc\xe9phalographie permettent de d\xe9tecter, en surface du cuir chevelu, des variations particuli\xe8res dans l'activit\xe9 c\xe9r\xe9brale. Ces variations sont des \"marqueurs physiologiques\" et sont indicatrices de l'\xe9tat mental de l'utilisateur. Elles peuvent donc \xeatre utilis\xe9es comme source d'information par la machine afin de traduire en commande l'intention de l'utilisateur, comme le ferait un clavier par l'interm\xe9diaire de nos mains. Le potentiel P300 est un exemple de marqueur physiologique. Sa d\xe9tection constitue la base du fonctionnement d'une ICM permettant la communication \xe9crite : le P300 Matrix Speller. Cependant, l'information brute, c'est-\xe0-dire le signal obtenu par \xe9lectroenc\xe9phalographie, n'est pas exploitable telle quelle par la machine. Au pr\xe9alable, il est n\xe9cessaire de traiter le signal. Le traitement est constitu\xe9 de trois phases : le pr\xe9traitement, l'extraction des caract\xe9ristiques et la classification. L'objectif g\xe9n\xe9ral du traitement est de rendre possible la d\xe9tection des signaux d'int\xe9r\xeat ainsi que de r\xe9duire la quantit\xe9 de donn\xe9es \xe0 traiter."}),"\n",(0,s.jsx)(n.p,{children:"\xc0 l'issue de ce traitement, les signaux peuvent \xeatre utilis\xe9s par la machine. Dans le cas du P300 Matrix Speller, impl\xe9ment\xe9 sous le logiciel OpenViBE, les signaux corr\xe9l\xe9s \xe0 une stimulation permettent \xe0 l'utilisateur d'\xe9peler un mot en utilisant exclusivement son activit\xe9 c\xe9r\xe9brale."}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Mots cl\xe9s."})," Cognitique, Informatique, Interface Cerveau-Machine, marqueur physiologique, traitement du signal, P300 Matrix Speller, OpenViBE"]}),"\n",(0,s.jsx)(n.h2,{id:"abstract",children:"Abstract"}),"\n",(0,s.jsx)(n.p,{children:"A Brain-Computer Interface (BCI) is a direct communication pathway between the brain and an external device. The concept first emerges in Science-Fiction before becoming reality in the 1970's thanks to unprecedented Neuroscience advances."}),"\n",(0,s.jsx)(n.p,{children:'The discovery of the structures and mechanisms which are governing the functioning of the brain helps us understanding the nature of the signal linked with cerebral activity. Many non-invasive measuring devices such as electroencephalography can be used to detect specific changes in brain activity on the surface of the scalp. These variations are called "physiological markers" and are indicative of the mental state of the user. They can therefore be exploited by the machine to identify and translate the user\'s intents into commands, as a keyboard would do with the tap of our fingertips. The P300 wave is an example of physiological marker used to run a BCI based written communication device called "P300 Matrix Speller". However, the raw data (i.e. the signal displayed on the electroencephalograph) cannot be directly exploited by the machine : the signal requires to be processed. The processing can be divided into 3 parts : pre-processing, features extraction and classification. The main purpose is to allow the detection of the signals of interest and reduce the data size.'}),"\n",(0,s.jsx)(n.p,{children:"At the end of the processing, the signals are ready to be exploited by the machine. Using the P300 Matrix Speller implemented under OpenViBE, the whole procedure allows the user to spell a word, by the exclusive exploitation of his brain activity."}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Key-words."})," Cognitive Technology, Computer Sciences, Brain-Computer Interface, physiological marker, signal processing, P300 Matrix Speller, OpenViBE"]}),"\n",(0,s.jsx)(n.h2,{id:"remerciements",children:"Remerciements"}),"\n",(0,s.jsx)(n.p,{children:"Nous tenons \xe0 remercier notre tutrice L\xe9a Pillette, qui a su nous guider avec patience et bienveillance tout au long de la r\xe9alisation de ce projet et s'est toujours montr\xe9e enthousiaste et encourageante lors de nos nombreuses visites \xe0 Inria."}),"\n",(0,s.jsx)(n.p,{children:"Nous remercions \xe9galement \xc9ric Dazzan, pour ses conseils avis\xe9s et son \xe9coute, et Patrick Fischer, pour ses remarques et corrections concernant l'aspect math\xe9matique du traitement du signal."}),"\n",(0,s.jsx)(n.p,{children:"Enfin, nous remercions notre entourage pour leur soutien et leur aide quant \xe0 la relecture de ce m\xe9moire."}),"\n",(0,s.jsx)(n.h2,{id:"avant-propos",children:"Avant-propos"}),"\n",(0,s.jsxs)(n.p,{children:["Ce m\xe9moire a \xe9t\xe9 r\xe9alis\xe9 dans le cadre du projet",(0,s.jsx)(n.sup,{children:(0,s.jsx)(n.a,{href:"#user-content-fn-orga",id:"user-content-fnref-orga","data-footnote-ref":!0,"aria-describedby":"footnote-label",children:"1"})})," de 2\xe8me ann\xe9e de CPBx. Le sujet choisi refl\xe8te l'attrait des trois membres du groupe pour l'informatique, les math\xe9matiques, mais \xe9galement la cognitique, discipline qui nous \xe9tait jusqu'alors pratiquement inconnue. Afin de concilier nos int\xe9r\xeats, nous avons d\xe9cid\xe9 de travailler sur les Interfaces Cerveau-Machine, leur \xe9tude n\xe9cessitant des notions de traitement du signal, de programmation ainsi que des bases en biologie."]}),"\n",(0,s.jsx)(n.p,{children:"Nous consid\xe9rons ce projet comme une occasion de d\xe9couvrir, de nous approprier le concept d'Interface Cerveau-Machine et de nous d\xe9faire de visions parfois st\xe9r\xe9otyp\xe9es."}),"\n",(0,s.jsx)(n.p,{children:'Nous tenions en particulier \xe0 lever toutes les "bo\xeetes noires" inh\xe9rentes \xe0 la compr\xe9hension de ces dispositifs afin de proposer \xe0 nos lecteurs une explication qui soit la plus claire et compl\xe8te possible.'}),"\n",(0,s.jsx)(n.p,{children:"Dans l'imm\xe9diat, nous ne pouvons affirmer si nos parcours professionnels respectifs nous offriront de nouveau l'opportunit\xe9 de nous int\xe9resser \xe0 ce sujet. Cependant, nous sommes intimement convaincus que la recherche sur les Interfaces Cerveau-Machine n'en est encore qu'\xe0 ses balbutiements, et que des dispositifs plus sophistiqu\xe9s se d\xe9velopperont et se perfectionneront."}),"\n",(0,s.jsx)(n.h2,{id:"glossaire",children:"Glossaire"}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"ICM / BCI."}),' Une Interface Cerveau-Machine (ICM) ou Brain Computer Interface (BCI) est une interface de communication directe entre le cerveau et un dispositif externe (un ordinateur par exemple). La communication est qualifi\xe9e de "directe" car le fonctionnement des ICM ne repose pas sur les canaux de communication standards que sont les nerfs et les muscles mais sur la d\xe9tection de signaux repr\xe9sentatifs de l\'activit\xe9 c\xe9r\xe9brale.']}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"ICM invasives, non invasives."})," Une ICM invasive enregistre l'activit\xe9 c\xe9r\xe9brale de l'utilisateur par l'interm\xe9diaire d'\xe9lectrodes plac\xe9es en profondeur dans le cerveau, dont la pose n\xe9cessite d'avoir recours \xe0 la tr\xe9panation. Par opposition, l'utilisation d'une ICM non invasive ne requiert pas d'intervention chirurgicale, car les \xe9lectrodes sont plac\xe9es en surface du cuir chevelu et enregistrent des r\xe9sidus d'activit\xe9 c\xe9r\xe9brale."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"ICM r\xe9actives."})," Ce sont des ICM qui envoient des stimulations visuelles, auditives ou tactiles \xe0 leur utilisateur dans l'attente d'une r\xe9ponse. Elles s'opposent aux ICM actives, pour lesquelles l'utilisateur est \xe0 l'origine du processus de communication, qu'il contr\xf4le en modifiant son \xe9tat mental lorsqu'il le souhaite."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"\xc9lectroenc\xe9phalographie (EEG)."})," M\xe9thode d'exploration c\xe9r\xe9brale qui mesure l'activit\xe9 \xe9lectrique du cerveau par l'interm\xe9diaire d'\xe9lectrodes plac\xe9es en surface du cuir chevelu. Le trac\xe9 de l'activit\xe9 \xe9lectrique enregistr\xe9e est appel\xe9 \xe9lectroenc\xe9phalogramme."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Potentiel \xe9voqu\xe9."})," Modification du potentiel \xe9lectrique g\xe9n\xe9r\xe9 par le syst\xe8me nerveux en r\xe9ponse \xe0 une stimulation externe (pr\xe9sentation d'une image, d'un son...) ou interne (modification de l'attention, pr\xe9paration motrice...)."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"P300."}),' Potentiel \xe9voqu\xe9 particulier d\xe9tectable par \xe9lectroenc\xe9phalographie. La lettre "P" indique que son amplitude est positive, "300" d\xe9signe son temps de latence, en ms.']}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"P300 Matrix Speller."})," ICM permettant \xe0 l'utilisateur d'\xe9peler des mots sur un \xe9cran, en utilisant exclusivement son activit\xe9 c\xe9r\xe9brale. Son fonctionnement repose sur la g\xe9n\xe9ration et la d\xe9tection de potentiels P300."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"SNC."})," Le Syst\xe8me Nerveux Central est la partie du syst\xe8me nerveux comprenant l'enc\xe9phale et la moelle \xe9pini\xe8re."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"SNP."})," Le Syst\xe8me Nerveux P\xe9riph\xe9rique est la partie du syst\xe8me nerveux form\xe9e des ganglions, des nerfs externes au cerveau et de la moelle \xe9pini\xe8re."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Bruit (traitement du signal)."})," Toute composante non d\xe9sir\xe9e affectant la sortie d'un dispositif ind\xe9pendamment du signal pr\xe9sent \xe0 son entr\xe9e."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Artefacts (traitement du signal)."})," Un artefact est une erreur de mesure d'une grandeur caus\xe9e par la technique ou l'outil utilis\xe9."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Signal stationnaire."})," Signal dont les propri\xe9t\xe9s statistiques sont invariantes par translation dans le temps."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Analyse spectrale."})," Ensemble de techniques de description du signal dans le domaine des fr\xe9quences."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Classifieur."})," Famille d'algorithmes de classement statistique. Le r\xf4le d'un classifieur est de classer dans des groupes des \xe9chantillons qui ont des propri\xe9t\xe9s similaires."]}),"\n",(0,s.jsx)(n.h2,{id:"plan-du-m\xe9moire",children:"Plan du m\xe9moire"}),"\n",(0,s.jsxs)(n.ol,{children:["\n",(0,s.jsx)(n.li,{children:(0,s.jsx)(n.a,{href:"/docs/scolarite/cpbx/s4/projet/activite-cerebrale",children:"Activit\xe9 c\xe9r\xe9brale, origine des signaux exploitables"})}),"\n",(0,s.jsx)(n.li,{children:(0,s.jsx)(n.a,{href:"/docs/scolarite/cpbx/s4/projet/traitement-du-signal",children:"Traitement du signal et apprentissage"})}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.a,{href:"/docs/scolarite/cpbx/s4/projet/implementation-p300-speller",children:"Exp\xe9rimentation : impl\xe9mentation du P300 Matrix Speller"}),", suivie de la conclusion g\xe9n\xe9rale et de la bibliographie"]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Annexes :"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:["A. ",(0,s.jsx)(n.a,{href:"/docs/scolarite/cpbx/s4/projet/laplacien-de-surface",children:"Outils math\xe9matiques pour le filtrage spatial : le laplacien de surface"})]}),"\n",(0,s.jsxs)(n.li,{children:["B. ",(0,s.jsx)(n.a,{href:"/docs/scolarite/cpbx/s4/projet/fourier-et-ondelettes",children:"Explications math\xe9matiques : transform\xe9e de Fourier et ondelettes"})]}),"\n",(0,s.jsxs)(n.li,{children:["C. ",(0,s.jsx)(n.a,{href:"/docs/scolarite/cpbx/s4/projet/analyse-discriminante-lineaire",children:"Outils math\xe9matiques pour la classification"})]}),"\n",(0,s.jsxs)(n.li,{children:["D. ",(0,s.jsx)(n.a,{href:"/docs/scolarite/cpbx/s4/projet/boites-openvibe",children:'Description des "bo\xeetes" utilis\xe9es dans nos sc\xe9narios'})]}),"\n",(0,s.jsxs)(n.li,{children:["E. ",(0,s.jsx)(n.a,{href:"/docs/scolarite/cpbx/s4/projet/gestion-du-projet",children:"Gestion du projet"})]}),"\n"]}),"\n",(0,s.jsx)(n.h2,{id:"introduction",children:"Introduction"}),"\n",(0,s.jsx)(n.p,{children:"L'essoufflement de la Seconde R\xe9volution Industrielle et l'av\xe8nement de l'informatique sont \xe0 l'origine d'une imagination nouvelle : la vision d'un futur fantasmatique dans lequel la machine ne serait plus soumise \xe0 l'Homme mais fonctionnerait avec lui, comme en symbiose. Ces perspectives in\xe9dites donnent naissance au concept d'Interface Cerveau-Machine (ICM)."}),"\n",(0,s.jsx)(n.p,{children:"Le d\xe9veloppement des neurosciences permet la cr\xe9ation des premiers mod\xe8les r\xe9els d\xe8s 1970. Une d\xe9finition pr\xe9cise des ICM est alors propos\xe9e : il s'agit de syst\xe8mes permettant la communication directe entre le cerveau et un dispositif externe (un ordinateur par exemple). La communication est qualifi\xe9e de \"directe\" car le fonctionnement des ICM ne repose pas sur les canaux de communication \"standards\" que sont les nerfs et les muscles mais sur la d\xe9tection de signaux repr\xe9sentatifs de l'activit\xe9 c\xe9r\xe9brale. Cette particularit\xe9 justifie les int\xe9r\xeats m\xe9dicaux et cliniques inh\xe9rents au d\xe9veloppement des ICM. Parmi ces diff\xe9rents enjeux, la r\xe9habilitation des capacit\xe9s de communication est un th\xe8me central. En effet, de nombreux troubles neurologiques ou musculaires engendrent une inaptitude partielle ou totale de la personne atteinte \xe0 la communication. Par l'interm\xe9diaire des ICM, qui relient directement l'activit\xe9 c\xe9r\xe9brale \xe0 l'action \xe0 effectuer, il devient envisageable de cr\xe9er une forme de communication alternative, g\xe9n\xe9ralement \xe9crite, et ce sans aucune intervention des muscles."}),"\n",(0,s.jsx)(n.p,{children:"Ce projet a pour ambition d'expliquer la mise en place d'une ICM permettant la communication \xe9crite, en d\xe9taillant les transformations du signal depuis sa g\xe9n\xe9ration dans la bo\xeete cr\xe2nienne jusqu'\xe0 son interpr\xe9tation par la machine. Nous avons ax\xe9 notre r\xe9flexion et nos recherches sur le fonctionnement concret d'une ICM particuli\xe8re : le \"P300 Matrix Speller\". Cependant, la plupart des r\xe9sultats et explications propos\xe9s sont valables pour tout type d'ICM."}),"\n",(0,s.jsx)(n.p,{children:"Notre raisonnement, articul\xe9 en trois parties, suit la logique chronologique de la propagation du signal. De ce fait, nous commencerons par d\xe9terminer l'origine des signaux exploitables en explicitant leur lien avec l'activit\xe9 c\xe9r\xe9brale et l'\xe9tat mental de l'utilisateur. Nous passerons ensuite en revue les diff\xe9rentes \xe9tapes de traitement du signal, en nous attardant sur les \xe9l\xe9ments essentiels au traitement dans le cas du P300 Matrix Speller. Enfin, nous proposerons au lecteur une vision concr\xe8te du fonctionnement d'une ICM en d\xe9taillant notre exp\xe9rimentation : l'impl\xe9mentation du P300 Matrix Speller sous OpenViBE. Cette derni\xe8re partie permettra notamment d'expliquer la traduction en commande par la machine du signal re\xe7u, terminant ainsi la cha\xeene de communication."}),"\n","\n",(0,s.jsxs)(n.section,{"data-footnotes":!0,className:"footnotes",children:[(0,s.jsx)(n.h2,{className:"sr-only",id:"footnote-label",children:"Footnotes"}),"\n",(0,s.jsxs)(n.ol,{children:["\n",(0,s.jsxs)(n.li,{id:"user-content-fn-orga",children:["\n",(0,s.jsxs)(n.p,{children:["Il est \xe0 noter que l'organisation de ce projet est d\xe9taill\xe9e en annexe E (",(0,s.jsx)(n.a,{href:"/docs/scolarite/cpbx/s4/projet/gestion-du-projet",children:"Gestion du projet"}),"). ",(0,s.jsx)(n.a,{href:"#user-content-fnref-orga","data-footnote-backref":"","aria-label":"Back to reference 1",className:"data-footnote-backref",children:"\u21a9"})]}),"\n"]}),"\n"]}),"\n"]})]})}function d(e={}){const{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(u,{...e})}):u(e)}},28453(e,n,t){t.d(n,{R:()=>a,x:()=>o});var i=t(96540);const s={},r=i.createContext(s);function a(e){const n=i.useContext(r);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),i.createElement(r.Provider,{value:n},e.children)}}}]);